//! Map loading (M0-018): collision chunks and spawn points of `data/maps/<map>/`.
//!
//! `sim` does no I/O, so the server reads `chunks/c_{bx}_{bz}.bin` and hands the bytes to
//! [`CollisionChunk::from_bytes`]. The terrain binaries are git-ignored and regenerated by the
//! map pipeline (DEVELOPING.md "Map data"); a missing or damaged map is a startup error that
//! names the command, never a silent fall-back to an empty (walls-everywhere) world.

use std::fmt;
use std::path::{Path, PathBuf};

use frontline_sim::{CollisionChunk, CollisionData, Team, Vec3, World};
use serde::Deserialize;

/// Regeneration command quoted in every "map missing" error.
pub const REGEN_COMMAND: &str =
    "PYTHONPATH=tools/map-pipeline python3 -m map_pipeline m0 --seed 1 --out data/maps/m0";

#[derive(Debug)]
pub enum MapError {
    /// `data/maps/<map>/` could not be located.
    DataDirNotFound { map: String, searched: Vec<PathBuf> },
    /// The directory exists but has no (or unreadable) collision chunks.
    NoChunks { dir: PathBuf },
    Io { path: PathBuf, error: String },
    BadChunk { path: PathBuf, error: String },
    BadJson { path: PathBuf, error: String },
    /// `spawns.json` has no HQ point for this team.
    MissingHq { team: &'static str },
}

impl fmt::Display for MapError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let hint = format!(
            "terrain binaries are not committed; regenerate them from the repository root with:\n  {REGEN_COMMAND}\n(see DEVELOPING.md, section \"Map data\"); use --data-dir to point at another checkout"
        );
        match self {
            MapError::DataDirNotFound { map, searched } => {
                let list: Vec<String> = searched.iter().map(|p| p.display().to_string()).collect();
                write!(
                    f,
                    "map '{map}' not found (looked for data/maps/{map}/meta.json in: {}); {hint}",
                    list.join(", ")
                )
            }
            MapError::NoChunks { dir } => write!(
                f,
                "no collision chunks (c_*_*.bin) in {}; {hint}",
                dir.display()
            ),
            MapError::Io { path, error } => {
                write!(f, "cannot read {}: {error}; {hint}", path.display())
            }
            MapError::BadChunk { path, error } => write!(
                f,
                "collision chunk {} is invalid ({error}); {hint}",
                path.display()
            ),
            MapError::BadJson { path, error } => {
                write!(f, "cannot parse {}: {error}", path.display())
            }
            MapError::MissingHq { team } => write!(f, "spawns.json has no HQ point for {team}"),
        }
    }
}

impl std::error::Error for MapError {}

/// HQ spawn area of one team (`spawns.json`).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct HqSpawn {
    /// East / north in metres.
    pub x: f32,
    pub z: f32,
    pub y: f32,
    pub radius_m: f32,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct MapSpawns {
    /// Indexed by `Team as usize` (US, GER).
    pub hq: [HqSpawn; 2],
    /// Map centre the players face on spawn.
    pub center: (f32, f32),
}

/// A map ready to be installed into a [`World`].
#[derive(Debug, Clone)]
pub struct LoadedMap {
    pub name: String,
    pub collision: CollisionData,
    pub spawns: MapSpawns,
    pub chunk_count: usize,
}

#[derive(Deserialize)]
struct SpawnsFile {
    hq: std::collections::BTreeMap<String, HqEntry>,
}
#[derive(Deserialize)]
struct HqEntry {
    pos: [f32; 2],
    #[serde(default)]
    radius_m: Option<f32>,
    #[serde(default)]
    y_m: Option<f32>,
}
#[derive(Deserialize)]
struct MetaFile {
    crs: Option<CrsMeta>,
}
#[derive(Deserialize)]
struct CrsMeta {
    size_m: Option<f32>,
}

/// Finds the repository `data/` directory: `explicit` if given, otherwise the first ancestor of
/// the working directory or of the executable that holds `data/maps/<map>/meta.json`.
pub fn locate_data_dir(explicit: Option<&Path>, map: &str) -> Result<PathBuf, MapError> {
    let marker = |d: &Path| d.join("maps").join(map).join("meta.json").is_file();
    if let Some(d) = explicit {
        return if marker(d) {
            Ok(d.to_path_buf())
        } else {
            Err(MapError::DataDirNotFound {
                map: map.into(),
                searched: vec![d.to_path_buf()],
            })
        };
    }
    let mut searched = Vec::new();
    let mut starts: Vec<PathBuf> = Vec::new();
    if let Ok(cwd) = std::env::current_dir() {
        starts.push(cwd);
    }
    if let Ok(exe) = std::env::current_exe() {
        if let Some(p) = exe.parent() {
            starts.push(p.to_path_buf());
        }
    }
    for s in starts {
        for anc in s.ancestors() {
            let d = anc.join("data");
            if marker(&d) {
                return Ok(d);
            }
            if !searched.contains(&d) {
                searched.push(d);
            }
        }
    }
    searched.truncate(4);
    Err(MapError::DataDirNotFound {
        map: map.into(),
        searched,
    })
}

fn read(path: &Path) -> Result<Vec<u8>, MapError> {
    std::fs::read(path).map_err(|e| MapError::Io {
        path: path.to_path_buf(),
        error: e.to_string(),
    })
}

fn json<T: for<'de> Deserialize<'de>>(path: &Path) -> Result<T, MapError> {
    serde_json::from_slice(&read(path)?).map_err(|e| MapError::BadJson {
        path: path.to_path_buf(),
        error: e.to_string(),
    })
}

/// Parses `c_{bx}_{bz}.bin`.
fn parse_chunk_name(name: &str) -> Option<(i32, i32)> {
    let rest = name.strip_prefix("c_")?.strip_suffix(".bin")?;
    let (bx, bz) = rest.split_once('_')?;
    Some((bx.parse().ok()?, bz.parse().ok()?))
}

/// Loads `<data_dir>/maps/<map>/`: all collision chunks plus HQ spawns.
pub fn load_map(data_dir: &Path, map: &str) -> Result<LoadedMap, MapError> {
    let dir = data_dir.join("maps").join(map);
    let chunks_dir = dir.join("chunks");
    let rd = std::fs::read_dir(&chunks_dir).map_err(|_| MapError::NoChunks {
        dir: chunks_dir.clone(),
    })?;
    let mut names: Vec<(i32, i32, PathBuf)> = rd
        .filter_map(|e| e.ok())
        .filter_map(|e| {
            let name = e.file_name().to_string_lossy().into_owned();
            parse_chunk_name(&name).map(|(bx, bz)| (bx, bz, e.path()))
        })
        .collect();
    if names.is_empty() {
        return Err(MapError::NoChunks { dir: chunks_dir });
    }
    names.sort();
    let mut chunks = Vec::with_capacity(names.len());
    for (bx, bz, path) in &names {
        let bytes = read(path)?;
        chunks.push(
            CollisionChunk::from_bytes(*bx, *bz, &bytes).map_err(|e| MapError::BadChunk {
                path: path.clone(),
                error: e.to_string(),
            })?,
        );
    }
    let chunk_count = chunks.len();
    let collision = CollisionData::from_chunks(chunks);

    let spawns_file: SpawnsFile = json(&dir.join("spawns.json"))?;
    let hq_of = |key: &str, team: &'static str| -> Result<HqSpawn, MapError> {
        let e = spawns_file
            .hq
            .iter()
            .find(|(k, _)| k.eq_ignore_ascii_case(key))
            .map(|(_, v)| v)
            .ok_or(MapError::MissingHq { team })?;
        let (x, z) = (e.pos[0], e.pos[1]);
        let y = e
            .y_m
            .or_else(|| collision.height_at(x, z))
            .unwrap_or(0.0);
        Ok(HqSpawn {
            x,
            z,
            y,
            radius_m: e.radius_m.unwrap_or(20.0),
        })
    };
    let hq = [hq_of("us", "US")?, hq_of("ger", "GER")?];
    let meta: Option<MetaFile> = json(&dir.join("meta.json")).ok();
    let center = match meta.and_then(|m| m.crs).and_then(|c| c.size_m) {
        Some(s) if s > 0.0 => (s * 0.5, s * 0.5),
        _ => ((hq[0].x + hq[1].x) * 0.5, (hq[0].z + hq[1].z) * 0.5),
    };
    Ok(LoadedMap {
        name: map.to_string(),
        collision,
        spawns: MapSpawns { hq, center },
        chunk_count,
    })
}

impl LoadedMap {
    /// Installs the per-team respawn points and the map centre into `world`.
    pub fn apply_to(&self, world: &mut World) {
        for team in [Team::Us, Team::Ger] {
            let h = self.spawns.hq[team as usize];
            world.set_team_spawn(team, Vec3::new(h.x, h.y, h.z));
        }
        world.set_map_center(self.spawns.center.0, self.spawns.center.1);
    }

    /// Where a joining player appears: a deterministic spiral around the team's HQ point (inside
    /// the HQ radius), on the ground, facing the map centre.
    pub fn join_spawn(&self, player: u8, team: Team) -> (Vec3, f32) {
        join_spawn_at(Some(self), player, team)
    }
}

/// Join position/yaw; without a map the player appears at `(player, 0, 0)` like the old tests.
pub fn join_spawn_at(map: Option<&LoadedMap>, player: u8, team: Team) -> (Vec3, f32) {
    let Some(m) = map else {
        return (Vec3::new(player as f32, 0.0, 0.0), 0.0);
    };
    let h = m.spawns.hq[team as usize];
    // Golden-angle spiral: 1.6 m * sqrt(n) spacing, never beyond half the HQ radius.
    let n = player as f32 + 1.0;
    let r = (1.6 * n.sqrt()).min(h.radius_m * 0.5);
    let a = n * 2.399_963_1;
    let x = h.x + r * a.cos();
    let z = h.z + r * a.sin();
    let y = m.collision.height_at(x, z).map_or(h.y, |g| g + 0.02);
    let (cx, cz) = m.spawns.center;
    let yaw = if (cx - x).abs() + (cz - z).abs() > 1e-3 {
        (cx - x).atan2(cz - z)
    } else {
        0.0
    };
    (Vec3::new(x, y, z), yaw)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn chunk_names_parse() {
        assert_eq!(parse_chunk_name("c_0_3.bin"), Some((0, 3)));
        assert_eq!(parse_chunk_name("c_-1_12.bin"), Some((-1, 12)));
        assert_eq!(parse_chunk_name("b_0_3.bin"), None);
        assert_eq!(parse_chunk_name("c_0_3.txt"), None);
        assert_eq!(parse_chunk_name("c_x_3.bin"), None);
    }

    #[test]
    fn missing_data_dir_error_names_the_regeneration_command() {
        let tmp = std::env::temp_dir().join("frontline-no-such-data-dir");
        let e = locate_data_dir(Some(&tmp), "m0").unwrap_err().to_string();
        assert!(e.contains("map_pipeline m0 --seed 1"), "{e}");
        assert!(e.contains("DEVELOPING.md"), "{e}");
    }

    #[test]
    fn empty_chunk_dir_is_a_clear_error() {
        let dir = std::env::temp_dir().join(format!("frontline-empty-map-{}", std::process::id()));
        std::fs::create_dir_all(dir.join("maps/m0/chunks")).unwrap();
        let e = load_map(&dir, "m0").unwrap_err().to_string();
        std::fs::remove_dir_all(&dir).ok();
        assert!(e.contains("no collision chunks"), "{e}");
        assert!(e.contains("map_pipeline"), "{e}");
    }

    #[test]
    fn no_map_spawn_is_the_legacy_line() {
        let (p, yaw) = join_spawn_at(None, 7, Team::Ger);
        assert_eq!((p.x, p.y, p.z, yaw), (7.0, 0.0, 0.0, 0.0));
    }
}
